#!/usr/bin/env node
/*
 * POC-001 type generator.
 *
 * The only machine-structure source is contracts/poc/scenario.schema.json.
 * This script emits the browser-facing TypeScript types into
 * apps/web/demo/poc/generated/ so the reducer/API cannot drift into a second
 * hand-written business model.
 *
 * Usage:
 *   node scripts/poc/generate-types.mjs           # write generated files
 *   node scripts/poc/generate-types.mjs --check   # verify committed output
 */

import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { compile } from 'json-schema-to-typescript';

import { detectContractDefects } from '../../apps/web/demo/poc/validation/semantic-rules.mjs';

const GENERATOR_VERSION = '1.0.0';
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const SCHEMA_FILE = path.join(ROOT, 'contracts', 'poc', 'scenario.schema.json');
const OUTPUT_DIR = path.join(ROOT, 'apps', 'web', 'demo', 'poc', 'generated');
const TYPES_FILE = 'scenario.types.ts';
const INDEX_FILE = 'index.ts';
const MANIFEST_FILE = 'generation-manifest.json';

const checkOnly = process.argv.includes('--check');
const unknownArgs = process.argv.slice(2).filter((argument) => argument !== '--check');
if (unknownArgs.length > 0) {
  console.error(`Unknown argument(s): ${unknownArgs.join(' ')}`);
  console.error('Usage: node scripts/poc/generate-types.mjs [--check]');
  process.exit(2);
}

function sha256(buffer) {
  return createHash('sha256').update(buffer).digest('hex');
}

function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

function collectPrefixItems(node, found = []) {
  if (!node || typeof node !== 'object') return found;
  if (Array.isArray(node.prefixItems)) found.push(node.prefixItems);
  for (const value of Object.values(node)) {
    if (value && typeof value === 'object') collectPrefixItems(value, found);
  }
  return found;
}

function schemaToTsType(schema) {
  if (!schema || typeof schema !== 'object') return 'unknown';
  if (schema.const !== undefined) {
    return JSON.stringify(schema.const);
  }
  if (Array.isArray(schema.enum)) {
    return schema.enum.map((value) => JSON.stringify(value)).join(' | ');
  }
  if (schema.$ref) {
    const name = String(schema.$ref).split('/').pop();
    return name.replace(/(^|[-_])([a-z])/g, (_, prefix, letter) => `${prefix}${letter.toUpperCase()}`);
  }
  switch (schema.type) {
    case 'string':
      return 'string';
    case 'integer':
    case 'number':
      return 'number';
    case 'boolean':
      return 'boolean';
    case 'null':
      return 'null';
    case 'array':
      return `${schemaToTsType(schema.items)}[]`;
    case 'object':
      return 'Record<string, unknown>';
    default:
      return 'unknown';
  }
}

function tupleType(prefixItems) {
  return `[${prefixItems.map((item) => schemaToTsType(item)).join(', ')}]`;
}

function buildIndexContent(schemaSha256, typesSha256) {
  return `/**
 * Generated POC scenario types (POC-001). Do not edit by hand.
 * Source: contracts/poc/scenario.schema.json
 * Schema SHA-256: ${schemaSha256}
 * Types SHA-256: ${typesSha256}
 */
export * from './scenario.types';
export * from '../validation';

export const POC_GENERATED_SCHEMA_SHA256 = '${schemaSha256}';
`;
}

async function generate() {
  const schemaBytes = readFileSync(SCHEMA_FILE);
  const schemaSha256 = sha256(schemaBytes);
  const schema = JSON.parse(schemaBytes.toString('utf8'));
  const prefixItems = collectPrefixItems(schema);
  const contractDefects = detectContractDefects(schema);

  const compileSchema = clone(schema);
  compileSchema.title = 'ScenarioPackage'; // stable generated root name.

  const defectNote = contractDefects.length
    ? `\n * WARNING: ${contractDefects.length} contract defect(s) detected; see generation-manifest.json contractDefects.`
    : '';
  const bannerComment = `/**
 * AUTO-GENERATED by scripts/poc/generate-types.mjs (POC-001) — do not edit.
 * Source of truth: contracts/poc/scenario.schema.json
 * Schema SHA-256: ${schemaSha256} (schema byte size ${schemaBytes.length})
 * Generator version: ${GENERATOR_VERSION}
 *
 * The declarations mirror the frozen schema exactly.${defectNote}
 */`;

  const compiled = await compile(compileSchema, 'ScenarioPackage', {
    bannerComment,
    additionalProperties: false,
    declareExternallyReferenced: true,
    enableConstEnums: false,
    format: false,
    strictIndexSignatures: false,
    unreachableDefinitions: true,
    style: { singleQuote: true, semi: true, tabWidth: 2, printWidth: 100 },
  });

  let typesContent = compiled.trimEnd() + '\n';
  const neverIndexes = [...typesContent.matchAll(/never\[\]/g)].map((match) => match.index ?? -1);
  if (neverIndexes.length !== prefixItems.length) {
    throw new Error(
      `Type generator could not map prefixItems tuples: ${prefixItems.length} tuple(s) in schema but ${neverIndexes.length} "never[]" placeholder(s) in output.`,
    );
  }
  let offset = 0;
  prefixItems.forEach((items, index) => {
    const position = neverIndexes[index] + offset;
    const replacement = tupleType(items);
    typesContent = typesContent.slice(0, position) + replacement + typesContent.slice(position + 'never[]'.length);
    offset += replacement.length - 'never[]'.length;
  });

  if (!typesContent.includes('export interface ScenarioPackage')) {
    throw new Error('Compiled output does not contain `export interface ScenarioPackage`.');
  }

  const typesSha256 = sha256(Buffer.from(typesContent, 'utf8'));
  const indexContent = buildIndexContent(schemaSha256, typesSha256);

  const manifest = {
    generator: 'scripts/poc/generate-types.mjs',
    generatorVersion: GENERATOR_VERSION,
    schemaVersion: schema.properties?.manifest ? '1.0.0' : null,
    source: 'contracts/poc/scenario.schema.json',
    schemaSha256,
    schemaBytes: schemaBytes.length,
    typesFile: TYPES_FILE,
    typesSha256,
    typesBytes: Buffer.byteLength(typesContent, 'utf8'),
    prefixItemsTuples: prefixItems.length,
    contractDefects,
  };
  const manifestContent = `${JSON.stringify(manifest, null, 2)}\n`;

  const expected = new Map([
    [TYPES_FILE, typesContent],
    [INDEX_FILE, indexContent],
    [MANIFEST_FILE, manifestContent],
  ]);

  if (checkOnly) {
    const problems = [];
    for (const [file, content] of expected.entries()) {
      const fullPath = path.join(OUTPUT_DIR, file);
      if (!existsSync(fullPath)) {
        problems.push(`${file}: missing`);
        continue;
      }
      const current = readFileSync(fullPath, 'utf8');
      if (current !== content) {
        problems.push(`${file}: out of date (run node scripts/poc/generate-types.mjs)`);
      }
    }
    if (problems.length) {
      console.error('Generated types are not up to date:');
      for (const problem of problems) console.error(`- ${problem}`);
      process.exit(1);
    }
    console.log(`Generated types are up to date (schema sha256 ${schemaSha256}).`);
    return;
  }

  mkdirSync(OUTPUT_DIR, { recursive: true });
  for (const [file, content] of expected.entries()) {
    writeFileSync(path.join(OUTPUT_DIR, file), content, 'utf8');
  }
  console.log(`Wrote ${expected.size} file(s) to apps/web/demo/poc/generated/`);
  console.log(`Schema sha256: ${schemaSha256}`);
  console.log(`Types sha256:  ${typesSha256}`);
  if (contractDefects.length) {
    console.error('WARNING: frozen schema has contract defect(s):');
    for (const defect of contractDefects) {
      console.error(`- ${defect.code} ${defect.jsonPointer}`);
    }
  }
}

generate().catch((error) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
});
